effect.shader:
const vec3 LUMA = vec3(0.2126, 0.7152, 0.0722);

vec3 rgb2hsv(vec3 c) {
    vec4 K = vec4(0.0, -1.0/3.0, 2.0/3.0, -1.0);
    vec4 p = mix(vec4(c.bg, K.wz), vec4(c.gb, K.xy), step(c.b, c.g));
    vec4 q = mix(vec4(p.xyw, c.r), vec4(c.r, p.yzx), step(p.x, c.r));
    float d = q.x - min(q.w, q.y);
    float e = 1.0e-10;
    return vec3(abs(q.z + (q.w - q.y) / (6.0 * d + e)), d / (q.x + e), q.x);
}

void main() {
    vec4 c = texture(inputImg, acScreenNorm);
    vec3 hsv = rgb2hsv(c.rgb);
    float h = hsv.x * 360.0;
    float alvo = mod(hue, 360.0);
    float diff = abs(h - alvo);
    diff = min(diff, 360.0 - diff);
    float k = 1.0 - smoothstep(tolerance, tolerance + softness, diff);
    // Peso também pela saturação — cinza puro não "é cor".
    k *= smoothstep(0.1, 0.3, hsv.y);
    float cinza = dot(c.rgb, LUMA);
    fragColor = vec4(mix(vec3(cinza), c.rgb, k), c.a);
}
